    hi: "100 GB से अधिक RAM: बहुत बड़े सर्वरों के लिए सूत्र अनुमानित हैं — मानों को असली वर्कलोड से मिलाएँ।",
    ar: "أكثر من 100 جيجابايت من RAM: الصيغ تقريبية للخوادم الكبيرة جدًا — طابق القيم مع حملك الفعلي.",
    bn: "১০০ GB-এর বেশি RAM: অতি বড় সার্ভারে সূত্রগুলো আনুমানিক — মানগুলো বাস্তব ওয়ার্কলোডের সঙ্গে মিলিয়ে নিন।",
    pt: "Mais de 100 GB de RAM: em servidores muito grandes as fórmulas são aproximadas — confira os valores com a carga real.",
