    de: "Mehr als 100 GB RAM: Bei sehr großen Servern sind die Formeln nur Näherungen — Werte mit der realen Last abgleichen.",
    ja: "RAM が 100 GB を超えています。非常に大きなサーバーでは計算式は近似なので、実際のワークロードで確認してください。",
    id: "RAM lebih dari 100 GB: untuk server sangat besar rumusnya hanya perkiraan — cocokkan nilai dengan beban kerja nyata.",
    pa: "100 GB ਤੋਂ ਵੱਧ RAM: ਬਹੁਤ ਵੱਡੇ ਸਰਵਰਾਂ ਲਈ ਫਾਰਮੂਲੇ ਅੰਦਾਜ਼ਨ ਹਨ — ਮੁੱਲ ਅਸਲ ਵਰਕਲੋਡ ਨਾਲ ਮਿਲਾਓ।",
    jv: "RAM luwih saka 100 GB: kanggo server gedhe banget rumus mung kira-kira — cocogna nilai karo beban nyata.",
    te: "100 GB కంటే ఎక్కువ RAM: చాలా పెద్ద సర్వర్లకు సూత్రాలు సుమారు మాత్రమే — విలువలను నిజమైన వర్క్‌లోడ్‌తో సరిపోల్చండి.",
    tr: "100 GB'tan fazla RAM: çok büyük sunucularda formüller yaklaşıktır — değerleri gerçek iş yükünüzle doğrulayın.",
    ko: "RAM이 100GB를 넘습니다. 매우 큰 서버에서는 공식이 근사치이므로 실제 워크로드로 값을 검증하세요.",
    mr: "100 GB पेक्षा जास्त RAM: अतिशय मोठ्या सर्व्हरसाठी सूत्रे अंदाजे आहेत — मूल्ये प्रत्यक्ष वर्कलोडशी पडताळा.",
    vi: "RAM trên 100 GB: với máy chủ rất lớn, công thức chỉ mang tính xấp xỉ — hãy đối chiếu giá trị với tải thực tế.",
    ta: "100 GB-க்கும் அதிகமான RAM: மிகப் பெரிய சர்வர்களில் சூத்திரங்கள் தோராயமானவை — மதிப்புகளை உண்மையான பணிச்சுமையுடன் சரிபாருங்கள்.",
