  warnOomParallel: {
    en: "With {connections} connections and up to {workers} parallel workers, work_mem is already at its minimum and memory may still run out (OOM). Lower max_connections, put a pooler such as PgBouncer in front, or limit parallel workers.",
    ru: "При {connections} подключениях и до {workers} параллельных воркерах work_mem уже на минимуме, а памяти всё равно может не хватить (OOM). Уменьшите max_connections, поставьте пулер вроде PgBouncer или ограничьте параллельные воркеры.",
    zh: "在 {connections} 个连接和最多 {workers} 个并行工作进程下，work_mem 已是最小值，内存仍可能耗尽（OOM）。请降低 max_connections，在前面加 PgBouncer 等连接池，或限制并行工作进程数。",
    es: "Con {connections} conexiones y hasta {workers} workers paralelos, work_mem ya está al mínimo y aun así puede agotarse la memoria (OOM). Reduzca max_connections, use un pooler como PgBouncer o limite los workers paralelos.",
    hi: "{connections} कनेक्शन और अधिकतम {workers} पैरेलल वर्कर पर work_mem पहले ही न्यूनतम है और फिर भी मेमोरी खत्म हो सकती है (OOM)। max_connections घटाएँ, PgBouncer जैसा पूलर लगाएँ या पैरेलल वर्कर सीमित करें।",
    ar: "مع {connections} اتصالًا وحتى {workers} عامل متوازٍ، work_mem عند حدّه الأدنى وقد تنفد الذاكرة رغم ذلك (OOM). خفّض max_connections أو ضع مجمّع اتصالات مثل PgBouncer أو قيّد العمال المتوازين.",
    bn: "{connections}টি সংযোগ ও সর্বোচ্চ {workers}টি প্যারালাল ওয়ার্কারে work_mem ইতিমধ্যে সর্বনিম্ন, তবু মেমরি শেষ হতে পারে (OOM)। max_connections কমান, PgBouncer-এর মতো পুলার বসান বা প্যারালাল ওয়ার্কার সীমিত করুন।",
    pt: "Com {connections} ligações e até {workers} workers paralelos, work_mem já está no mínimo e a memória ainda pode esgotar-se (OOM). Reduza max_connections, use um pooler como o PgBouncer ou limite os workers paralelos.",
    fr: "Avec {connections} connexions et jusqu’à {workers} workers parallèles, work_mem est déjà au minimum et la mémoire peut quand même manquer (OOM). Réduisez max_connections, placez un pooler comme PgBouncer ou limitez les workers parallèles.",
    de: "Bei {connections} Verbindungen und bis zu {workers} parallelen Workern steht work_mem schon auf dem Minimum, und der Speicher kann trotzdem knapp werden (OOM). max_connections senken, einen Pooler wie PgBouncer vorschalten oder parallele Worker begrenzen.",
    ja: "接続数 {connections}、並列ワーカー最大 {workers} の条件では work_mem がすでに最小値で、それでもメモリ不足（OOM）になり得ます。max_connections を下げるか、PgBouncer などのプーラーを前段に置くか、並列ワーカーを制限してください。",
    id: "Dengan {connections} koneksi dan hingga {workers} worker paralel, work_mem sudah minimum dan memori tetap bisa habis (OOM). Turunkan max_connections, pasang pooler seperti PgBouncer, atau batasi worker paralel.",
    pa: "{connections} ਕਨੈਕਸ਼ਨ ਅਤੇ {workers} ਤੱਕ ਪੈਰਲਲ ਵਰਕਰਾਂ ਨਾਲ work_mem ਪਹਿਲਾਂ ਹੀ ਘੱਟੋ-ਘੱਟ ਹੈ ਤੇ ਫਿਰ ਵੀ ਮੈਮੋਰੀ ਮੁੱਕ ਸਕਦੀ ਹੈ (OOM)। max_connections ਘਟਾਓ, PgBouncer ਵਰਗਾ ਪੂਲਰ ਲਾਓ ਜਾਂ ਪੈਰਲਲ ਵਰਕਰ ਸੀਮਤ ਕਰੋ।",
    jv: "Kanthi {connections} sambungan lan nganti {workers} worker paralel, work_mem wis minimum lan memori isih bisa entek (OOM). Kurangi max_connections, pasang pooler kaya PgBouncer, utawa watesi worker paralel.",
    te: "{connections} కనెక్షన్లు మరియు గరిష్టంగా {workers} పారలల్ వర్కర్లతో work_mem ఇప్పటికే కనిష్టం, అయినా మెమరీ అయిపోవచ్చు (OOM). max_connections తగ్గించండి, PgBouncer వంటి పూలర్ ఉంచండి లేదా పారలల్ వర్కర్లను పరిమితం చేయండి.",
    tr: "{connections} bağlantı ve en fazla {workers} paralel işçiyle work_mem zaten en düşük değerde, yine de bellek yetmeyebilir (OOM). max_connections değerini düşürün, önüne PgBouncer gibi bir havuzlayıcı koyun veya paralel işçileri sınırlayın.",
    ko: "연결 {connections}개와 병렬 워커 최대 {workers}개 조건에서는 work_mem이 이미 최솟값이며, 그래도 메모리가 부족(OOM)할 수 있습니다. max_connections를 낮추거나 PgBouncer 같은 풀러를 앞에 두거나 병렬 워커를 제한하세요.",
    mr: "{connections} कनेक्शन आणि कमाल {workers} पॅरलल वर्कर्सवर work_mem आधीच किमान आहे आणि तरीही मेमरी संपू शकते (OOM). max_connections कमी करा, PgBouncer सारखा पूलर लावा किंवा पॅरलल वर्कर्स मर्यादित करा.",
    vi: "Với {connections} kết nối và tối đa {workers} worker song song, work_mem đã ở mức tối thiểu mà bộ nhớ vẫn có thể cạn (OOM). Hãy giảm max_connections, đặt pooler như PgBouncer phía trước hoặc giới hạn worker song song.",
    ta: "{connections} இணைப்புகள் மற்றும் அதிகபட்சம் {workers} இணை வொர்க்கர்களுடன் work_mem ஏற்கனவே குறைந்தபட்சம், அப்படியும் நினைவகம் தீரலாம் (OOM). max_connections-ஐ குறையுங்கள், PgBouncer போன்ற பூலரை முன்னே வையுங்கள் அல்லது இணை வொர்க்கர்களை வரையறுங்கள்.",
    it: "Con {connections} connessioni e fino a {workers} worker paralleli, work_mem è già al minimo e la memoria potrebbe comunque esaurirsi (OOM). Riduci max_connections, metti davanti un pooler come PgBouncer o limita i worker paralleli.",
    fa: "با {connections} اتصال و حداکثر {workers} ورکر موازی، work_mem از قبل در حداقل است و باز هم ممکن است حافظه تمام شود (OOM). max_connections را کم کنید، پولری مثل PgBouncer جلوی آن بگذارید یا ورکرهای موازی را محدود کنید.",
    tlh: "{connections} yo' {workers} ngeD je: work_mem puS 'ej qaw tlhoS laH (OOM). max_connections yIpum, PgBouncer yIlan, pagh parallel worker yIlaj.",
  },
