    pt: "Com {connections} ligações, work_mem já está no mínimo e a memória ainda pode esgotar-se (OOM). Reduza max_connections ou use um pooler como o PgBouncer.",
    fr: "Avec {connections} connexions, work_mem est déjà au minimum et la mémoire peut quand même manquer (OOM). Réduisez max_connections ou placez un pooler comme PgBouncer.",
    de: "Bei {connections} Verbindungen steht work_mem schon auf dem Minimum, und der Speicher kann trotzdem knapp werden (OOM). max_connections senken oder einen Pooler wie PgBouncer vorschalten.",
