    ar: "ذاكرة لسجل WAL الذي لم يُكتب إلى القرص بعد. تُشتق من shared_buffers وتتراوح بين 64 كيلوبايت و16 ميجابايت.",
    bn: "এখনো ডিস্কে না লেখা WAL-এর জন্য মেমরি। shared_buffers থেকে নির্ধারিত, ৬৪ kB থেকে ১৬ MB-এর মধ্যে।",
    pt: "Memória para o WAL ainda não gravado em disco. Derivada de shared_buffers, entre 64 kB e 16 MB.",
    fr: "Mémoire pour le WAL pas encore écrit sur disque. Dérivée de shared_buffers, entre 64 ko et 16 Mo.",
    de: "Speicher für noch nicht geschriebenes WAL. Aus shared_buffers abgeleitet, zwischen 64 kB und 16 MB.",
