    id: "Memori untuk WAL yang belum ditulis ke disk. Diturunkan dari shared_buffers, antara 64 kB dan 16 MB.",
    pa: "ਹਾਲੇ ਡਿਸਕ ਉੱਤੇ ਨਾ ਲਿਖੇ WAL ਲਈ ਮੈਮੋਰੀ। shared_buffers ਤੋਂ ਕੱਢੀ ਜਾਂਦੀ ਹੈ, 64 kB ਤੋਂ 16 MB ਵਿਚਕਾਰ।",
