    zh: "规划器统计信息的详细程度。数据仓库取 500 可让复杂查询得到更好的执行计划，代价是 ANALYZE 更慢。",
    es: "Nivel de detalle de las estadísticas del planificador. 500 en almacenes de datos mejora los planes de consultas complejas, a costa de un ANALYZE más lento.",
