    ar: "مستوى تفصيل إحصاءات المخطِّط. القيمة 500 لمستودعات البيانات تعطي خططًا أفضل للاستعلامات المعقدة على حساب بطء ANALYZE.",
    bn: "প্ল্যানার পরিসংখ্যানের বিস্তারিততা। ডেটা ওয়্যারহাউসে ৫০০ জটিল কোয়েরির ভালো প্ল্যান দেয়, তবে ANALYZE ধীর হয়।",
    pt: "Nível de detalhe das estatísticas do planeador. 500 em data warehouses dá melhores planos em consultas complexas, ao custo de um ANALYZE mais lento.",
