    de: "Detailgrad der Planer-Statistiken. 500 für Data Warehouses liefert bessere Pläne bei komplexen Abfragen, dafür ist ANALYZE langsamer.",
    ja: "プランナー統計の詳細度です。データウェアハウスでは 500 にすると複雑なクエリの実行計画が改善しますが、ANALYZE が遅くなります。",
    id: "Tingkat detail statistik planner. 500 untuk data warehouse menghasilkan rencana lebih baik pada kueri kompleks, dengan ANALYZE yang lebih lambat.",
