    tr: "Planlayıcı istatistiklerinin ayrıntı düzeyi. Veri ambarları için 500, karmaşık sorgularda daha iyi planlar verir; bedeli daha yavaş ANALYZE'dır.",
    ko: "플래너 통계의 상세 수준입니다. 데이터 웨어하우스에서 500은 복잡한 쿼리의 실행 계획을 개선하지만 ANALYZE가 느려집니다.",
    mr: "प्लॅनर आकडेवारीची तपशील पातळी. डेटा वेअरहाउससाठी 500 गुंतागुंतीच्या क्वेरींचे चांगले प्लॅन देते, पण ANALYZE हळू होते.",
    vi: "Mức chi tiết của thống kê planner. 500 cho kho dữ liệu giúp kế hoạch truy vấn phức tạp tốt hơn, đổi lại ANALYZE chậm hơn.",
