    te: "అసింక్రోనస్ I/O పద్ధతి (PostgreSQL 18+). Linux లో io_uring, I/O వర్కర్ ప్రాసెస్ పూల్ కంటే రీడ్ లేటెన్సీని తగ్గిస్తుంది.",
    tr: "Eşzamansız G/Ç yöntemi (PostgreSQL 18+). Linux'ta io_uring, G/Ç işçi süreçleri havuzuna göre okuma gecikmesini düşürür.",
    ko: "비동기 I/O 방식입니다(PostgreSQL 18+). Linux에서는 io_uring이 I/O 워커 프로세스 풀보다 읽기 지연을 줄여 줍니다.",
    mr: "असिंक्रोनस I/O पद्धत (PostgreSQL 18+). Linux वर io_uring, I/O वर्कर प्रोसेस पूलच्या तुलनेत रीड लेटन्सी कमी करते.",
    vi: "Phương thức I/O bất đồng bộ (PostgreSQL 18+). Trên Linux, io_uring giảm độ trễ đọc so với nhóm tiến trình worker I/O.",
    ta: "ஒத்திசைவற்ற I/O முறை (PostgreSQL 18+). Linux-இல் io_uring, I/O வொர்க்கர் செயல்முறைக் குழுவை விட வாசிப்புத் தாமதத்தைக் குறைக்கும்.",
