  why_wal_level: {
    en: "minimal writes the least WAL, which suits a single desktop instance. It disables replication and archiving and needs a restart.",
    ru: "minimal пишет минимум WAL, что подходит одиночному desktop-инстансу. Отключает репликацию и архивирование, требует перезапуска.",
    zh: "minimal 写入的 WAL 最少，适合单机桌面实例。它会禁用复制和归档，且需要重启。",
    es: "minimal escribe el mínimo de WAL, adecuado para una instancia de escritorio única. Desactiva la replicación y el archivado y requiere reinicio.",
    hi: "minimal सबसे कम WAL लिखता है, जो एकल डेस्कटॉप इंस्टेंस के लिए उपयुक्त है। यह रेप्लिकेशन और आर्काइविंग बंद करता है और रीस्टार्ट माँगता है।",
    ar: "يكتب minimal أقل قدر من WAL ويناسب نسخة سطح مكتب مفردة. يعطّل النسخ المتماثل والأرشفة ويتطلب إعادة التشغيل.",
    bn: "minimal সবচেয়ে কম WAL লেখে, যা একক ডেস্কটপ ইনস্ট্যান্সের জন্য উপযুক্ত। এটি রেপ্লিকেশন ও আর্কাইভিং বন্ধ করে এবং রিস্টার্ট লাগে।",
    pt: "minimal escreve o mínimo de WAL, adequado a uma instância desktop única. Desativa a replicação e o arquivamento e requer reinício.",
    fr: "minimal écrit le moins de WAL, ce qui convient à une instance de poste de travail unique. Il désactive réplication et archivage et exige un redémarrage.",
    de: "minimal schreibt am wenigsten WAL und passt zu einer einzelnen Desktop-Instanz. Es deaktiviert Replikation und Archivierung und erfordert einen Neustart.",
    ja: "minimal は WAL の書き込みが最小で、単独のデスクトップ用インスタンスに向きます。レプリケーションとアーカイブが無効になり、再起動が必要です。",
    id: "minimal menulis WAL paling sedikit, cocok untuk satu instans desktop. Menonaktifkan replikasi dan pengarsipan serta perlu restart.",
    pa: "minimal ਸਭ ਤੋਂ ਘੱਟ WAL ਲਿਖਦਾ ਹੈ, ਜੋ ਇਕੱਲੇ ਡੈਸਕਟੌਪ ਇੰਸਟੈਂਸ ਲਈ ਠੀਕ ਹੈ। ਇਹ ਰੈਪਲੀਕੇਸ਼ਨ ਤੇ ਆਰਕਾਈਵਿੰਗ ਬੰਦ ਕਰਦਾ ਹੈ ਅਤੇ ਰੀਸਟਾਰਟ ਮੰਗਦਾ ਹੈ।",
    jv: "minimal nulis WAL paling sithik, cocog kanggo siji instans desktop. Mateni replikasi lan pengarsipan lan butuh restart.",
    te: "minimal అతి తక్కువ WAL రాస్తుంది, ఒకే డెస్క్‌టాప్ ఇన్‌స్టాన్స్‌కు సరిపోతుంది. ఇది రెప్లికేషన్, ఆర్కైవింగ్‌ను నిలిపివేస్తుంది మరియు రీస్టార్ట్ అవసరం.",
    tr: "minimal en az WAL yazar ve tek bir masaüstü örneğine uygundur. Replikasyonu ve arşivlemeyi devre dışı bırakır, yeniden başlatma gerektirir.",
    ko: "minimal은 WAL을 가장 적게 기록해 단일 데스크톱 인스턴스에 적합합니다. 복제와 아카이빙이 꺼지며 재시작이 필요합니다.",
    mr: "minimal सर्वात कमी WAL लिहिते, जे एकाच डेस्कटॉप इन्स्टन्ससाठी योग्य आहे. ते रेप्लिकेशन आणि आर्काइव्हिंग बंद करते आणि रीस्टार्ट लागतो.",
    vi: "minimal ghi ít WAL nhất, phù hợp một phiên bản desktop đơn lẻ. Nó tắt sao chép và lưu trữ, và cần khởi động lại.",
    ta: "minimal மிகக் குறைந்த WAL எழுதுகிறது; ஒற்றை டெஸ்க்டாப் நிகழ்வுக்கு ஏற்றது. இது பிரதியாக்கம், காப்பகத்தை முடக்கும்; மறுதொடக்கம் தேவை.",
    it: "minimal scrive meno WAL possibile, adatto a una singola istanza desktop. Disattiva replica e archiviazione e richiede riavvio.",
    fa: "minimal کمترین WAL را می‌نویسد و برای یک نمونهٔ دسکتاپ مناسب است. همانندسازی و بایگانی را غیرفعال می‌کند و به راه‌اندازی مجدد نیاز دارد.",
    tlh: "minimal WAL puS ghItlh: wa' DaH Qu' Daq QaQ. replication archive je mej, DoH poQ.",
  },
