    te: "{n} తాత్కాలిక ఫైళ్లు సృష్టించబడ్డాయి: కొన్ని సార్ట్‌లు లేదా హ్యాష్‌లు డిస్క్‌కు వెళ్తున్నాయి. work_mem, నెమ్మదైన క్వెరీలను పరిశీలించండి.",
