    mr: "postgresql.conf चा भाग किंवा SHOW ALL आउटपुट पेस्ट करा. शिफारशीशी तुलना होईल आणि जोखीम दाखवल्या जातील, सर्व ब्राउझरमध्ये.",
    pa: "postgresql.conf ਦਾ ਹਿੱਸਾ ਜਾਂ SHOW ALL ਦਾ ਆਉਟਪੁੱਟ ਪੇਸਟ ਕਰੋ। ਸਿਫ਼ਾਰਸ਼ ਨਾਲ ਤੁਲਨਾ ਹੋਵੇਗੀ ਅਤੇ ਜੋਖਮ ਦਿਖਾਏ ਜਾਣਗੇ, ਸਭ ਬ੍ਰਾਊਜ਼ਰ ਵਿੱਚ।",
    pt: "Cole um excerto de postgresql.conf ou a saída de SHOW ALL. Compara-se com a recomendação e assinalam-se os riscos, tudo no navegador.",
    ta: "postgresql.conf பகுதி அல்லது SHOW ALL வெளியீட்டை ஒட்டுங்கள். பரிந்துரையுடன் ஒப்பிட்டு அபாயங்களைக் காட்டுவோம், எல்லாம் உலாவியில்.",
    te: "postgresql.conf భాగాన్ని లేదా SHOW ALL అవుట్‌పుట్‌ను అతికించండి. సిఫార్సుతో పోల్చి ప్రమాదాలను చూపిస్తాం, అంతా బ్రౌజర్‌లోనే.",
    tr: "postgresql.conf parçasını veya SHOW ALL çıktısını yapıştırın. Öneriyle karşılaştırılır ve riskler işaretlenir, hepsi tarayıcıda.",
    vi: "Dán đoạn postgresql.conf hoặc đầu ra SHOW ALL. Hệ thống so sánh với khuyến nghị và đánh dấu rủi ro, tất cả trong trình duyệt.",
    zh: "粘贴 postgresql.conf 片段或 SHOW ALL 输出，将与推荐值对比并标出风险，全部在浏览器中完成。",
    it: "Incolla un estratto di postgresql.conf o l’output di SHOW ALL. Viene confrontato con la raccomandazione e i rischi vengono segnalati, tutto nel browser.",
    fa: "بخشی از postgresql.conf یا خروجی SHOW ALL را بچسبانید. با توصیه مقایسه می‌شود و ریسک‌ها مشخص می‌شوند، همه در مرورگر.",
    tlh: "postgresql.conf Hap pagh SHOW ALL yIQoy. ghuH ghItlh mIw, Hoch lIjwI'Daq.",
    bg: "Поставете фрагмент от postgresql.conf или изход на SHOW ALL — ще го сравним с препоръката и ще изброим рисковете.",
