    el: "Επικολλήστε απόσπασμα postgresql.conf ή έξοδο SHOW ALL — θα τη συγκρίνουμε με τη σύσταση και θα απαριθμήσουμε τους κινδύνους.",
    et: "Kleepige postgresql.conf-i lõik või SHOW ALL väljund — võrdleme seda soovitusega ja loetleme riskid.",
    fi: "Liitä postgresql.conf-ote tai SHOW ALL -tuloste — vertaamme sitä suositukseen ja listaamme riskit.",
    he: "הדביקו קטע postgresql.conf או פלט SHOW ALL — נשווה אותו להמלצה ונפרט סיכונים.",
    hr: "Zalijepite isječak postgresql.conf ili izlaz SHOW ALL — usporedit ćemo ga s preporukom i navesti rizike.",
    hu: "Illesszen be egy postgresql.conf-részletet vagy SHOW ALL kimenetet — összehasonlítjuk az ajánlással, és felsoroljuk a kockázatokat.",
