    te: "AWS RDS: సెట్టింగ్‌లను పారామీటర్ గ్రూప్ ద్వారా మార్చండి; ప్లాట్‌ఫామ్ స్వయంగా నిర్వహించేవి వదిలివేయబడ్డాయి.",
