    ar: "shared_buffers مضبوط لكن effective_cache_size غير مضبوط، فقد يقلّل المخطِّط من تقدير ذاكرة التخزين المؤقت للنظام.",
    bn: "shared_buffers সেট আছে কিন্তু effective_cache_size নেই, তাই প্ল্যানার OS ক্যাশ কম ধরতে পারে।",
